import { Group, Mesh, PointLight, CapsuleGeometry, PlaneGeometry, Color, MeshBasicMaterial, DoubleSide, CircleGeometry } from 'three/webgpu';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uniform, vec3, float, dot, normalWorld, positionViewDirection, pow, mix, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new (THREE?.Group ?? Group)();
  group.name = 'journal-badge';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = new Color(colors.ink);
  const accentColor = new Color(colors.accent);
  const paperColor = new Color(colors.paper);

  // ---- Capsule badge shell (machined-metal PBR with accent fresnel rim) ----
  const capsuleGeo = new CapsuleGeometry(0.16, 0.62, 6, 16);
  capsuleGeo.rotateZ(Math.PI / 2);

  const rimStrength = uniform(1.4);
  const accentU = uniform(vec3(accentColor.r, accentColor.g, accentColor.b));

  const fresnel = pow(
    float(1.0).sub(dot(normalWorld, positionViewDirection).clamp(0.0, 1.0)),
    float(2.4)
  ).mul(rimStrength);

  const capsuleMat = new MeshPhysicalNodeMaterial();
  capsuleMat.color = inkColor;
  capsuleMat.metalness = 0.5;
  capsuleMat.roughness = 0.55;
  capsuleMat.clearcoat = 0.18;
  capsuleMat.clearcoatRoughness = 0.4;
  capsuleMat.emissiveNode = accentU.mul(fresnel);

  const capsuleMesh = new Mesh(capsuleGeo, capsuleMat);
  capsuleMesh.position.set(0, 0, 0);
  group.add(capsuleMesh);

  // subtle paper-toned inner highlight plane behind capsule (depth layer 2)
  const innerGeo = new CapsuleGeometry(0.11, 0.5, 4, 12);
  innerGeo.rotateZ(Math.PI / 2);
  const innerMat = new MeshPhysicalNodeMaterial();
  innerMat.color = paperColor;
  innerMat.metalness = 0.15;
  innerMat.roughness = 0.65;
  innerMat.emissive = new Color(0x000000);
  const innerMesh = new Mesh(innerGeo, innerMat);
  innerMesh.position.z = 0.03;
  innerMesh.scale.set(0.94, 0.9, 0.7);
  group.add(innerMesh);

  // ---- Accent rim light (node-local, intensity capped) ----
  const rimLight = new PointLight(accentColor, 1.1, 3.2, 2.0);
  rimLight.position.set(-0.35, 0.15, 0.45);
  group.add(rimLight);

  const fillLight = new PointLight(accentColor, 0.35, 2.4, 2.0);
  fillLight.position.set(0.4, -0.2, -0.3);
  group.add(fillLight);

  // ---- Contact shadow plane (grounded accent) ----
  const shadowGeo = new CircleGeometry(0.55, 24);
  const shadowMat = new MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.45,
    side: DoubleSide,
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.28, 0);
  group.add(shadowMesh);

  // ---- Optional gear GLB as small foreground accent inside badge (depth layer 3) ----
  let gearScene = null;
  const meshUrl = config?.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      gearScene = gltf.scene ?? gltf;
      gearScene.scale.setScalar(0.09);
      gearScene.position.set(0.18, 0, 0.12);
      gearScene.traverse((child) => {
        if (child.isMesh && child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            if ('metalness' in m) m.metalness = Math.min(m.metalness ?? 0.5, 0.55);
            if ('roughness' in m) m.roughness = Math.max(m.roughness ?? 0.5, 0.5);
            if ('clearcoat' in m) m.clearcoat = Math.min(m.clearcoat ?? 0, 0.25);
          });
        }
      });
      group.add(gearScene);
      gsap.fromTo(
        gearScene.rotation,
        { y: 0 },
        { y: Math.PI * 2, duration: 12, repeat: -1, ease: 'none' }
      );
    }).catch(() => {});
  }

  // ---- Cinematic primitives ----
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        const handle = fn(group, prim.params ?? {});
        primitiveHandles.push(handle);
      }
    }
  }

  // ---- Entrance: weighted-settle ----
  const entranceTl = gsap.timeline();
  group.scale.setScalar(0.001);
  entranceTl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // ---- Hover: rise-in (subtle 0.15 units) ----
  const baseY = group.position.y;
  let hoverTl = null;

  function onPointerEnter() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power2.out',
    });
    hoverTl.to(rimStrength, { value: 2.0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onPointerLeave() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    });
    hoverTl.to(rimStrength, { value: 1.4, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onClick() {
    gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
    ctx.emit?.('hub-journal.select', { nodeId: config?.id ?? 'hub-journal-badge' });
  }

  group.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerover: onPointerEnter,
    pointerleave: onPointerLeave,
    pointerout: onPointerLeave,
    click: onClick,
  };

  group.userData.cleanup = () => {
    entranceTl.kill();
    if (hoverTl) hoverTl.kill();
    primitiveHandles.forEach((h) => h?.cleanup?.());

    capsuleGeo.dispose();
    capsuleMat.dispose();
    innerGeo.dispose();
    innerMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    group.remove(rimLight);
    group.remove(fillLight);

    if (gearScene) {
      gearScene.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose?.();
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => m?.dispose?.());
        }
      });
    }
  };

  return group;
}
